begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
-- Comunicação · séries de mensagens e ordem dos episódios no app.
create function pg_temp.sv(t text) returns uuid language sql immutable as $$select md5('series-videos-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.sv(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.sv(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-series@example.invalid',now(),now(),now() from unnest(array['owner','reader'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.sv('org'),'Séries fictício','series-videos-test','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.sv('a'),pg_temp.sv('org'),'Igreja A','a','headquarters'),(pg_temp.sv('b'),pg_temp.sv('org'),'Igreja B','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) values
 (pg_temp.sv('owner-m'),pg_temp.sv('org'),pg_temp.sv('owner'),pg_temp.sv('a'),'owner','active'),(pg_temp.sv('reader-m'),pg_temp.sv('org'),pg_temp.sv('reader'),pg_temp.sv('a'),'member','active');
create function pg_temp.pub(a text,i text default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.publishing_admin(pg_temp.sv('org'),pg_temp.sv('a'),a,case when i is null then null else pg_temp.sv(i) end,v,d)$$;
create function pg_temp.fields(k text,title text,source text default '',cat text default '') returns jsonb language sql as $$select jsonb_build_object('kind',k,'title',title,'body','Descrição de '||title,'source',source,'poster','','category',cat,'channel','','scope','local','targets',jsonb_build_array(pg_temp.sv('a')),'group','','groupVersion',0,'provider','','starts','','ends','','download',false,'share',true)$$;
create function pg_temp.yt(n int) returns text language sql immutable as $$select 'https://www.youtube.com/watch?v=abcdefghij'||n$$;
select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select pg_temp.pub('save','serie',0,pg_temp.fields('series','Série Esperança'))$$,'cria série');
select throws_ok($$select pg_temp.pub('save','serie-link',0,pg_temp.fields('series','Com link','https://exemplo.invalid/x'))$$,'22023',null,'série não tem link');
select throws_ok($$select pg_temp.pub('save','ep-early',0,pg_temp.fields('video','Antes da hora',pg_temp.yt(9),pg_temp.sv('serie')::text))$$,'22023',null,'vídeo só entra em série publicada');
select lives_ok($$select pg_temp.pub('publish','serie',1)$$,'série publicada');
select is((select string_agg(x->>'title',',') from jsonb_array_elements(pg_temp.pub('list',null,null,'{"kind":"video"}')->'series') x),'Série Esperança','painel lista a série para os vídeos');
select lives_ok($$select pg_temp.pub('save','ep1',0,pg_temp.fields('video','Parte 1',pg_temp.yt(1),pg_temp.sv('serie')::text))$$,'episódio 1');
select lives_ok($$select pg_temp.pub('save','ep2',0,pg_temp.fields('video','Parte 2',pg_temp.yt(2),pg_temp.sv('serie')::text))$$,'episódio 2');
select lives_ok($$select pg_temp.pub('save','solo',0,pg_temp.fields('video','Avulso',pg_temp.yt(3)))$$,'vídeo avulso');
select lives_ok($$select pg_temp.pub('publish','ep1',1)$$,'publica 1');
select lives_ok($$select pg_temp.pub('publish','ep2',1)$$,'publica 2');
select lives_ok($$select pg_temp.pub('publish','solo',1)$$,'publica avulso');
select throws_ok($$select pg_temp.pub('save','note-series',0,pg_temp.fields('notice','Aviso na série','',pg_temp.sv('serie')::text))$$,'22023',null,'só vídeo entra em série');
select is(jsonb_array_length(public.publishing_series_episodes(pg_temp.sv('org'),pg_temp.sv('a'),pg_temp.sv('serie'))->'items'),2,'painel lista os episódios');
select throws_ok($$select public.publishing_series_episodes(pg_temp.sv('org'),pg_temp.sv('a'),pg_temp.sv('serie'),array[pg_temp.sv('ep2')])$$,'40001',null,'ordem precisa da lista completa');
select throws_ok($$select public.publishing_series_episodes(pg_temp.sv('org'),pg_temp.sv('a'),pg_temp.sv('serie'),array[pg_temp.sv('ep2'),pg_temp.sv('solo')])$$,'40001',null,'vídeo de fora não entra na ordem');
select is((public.publishing_series_episodes(pg_temp.sv('org'),pg_temp.sv('a'),pg_temp.sv('serie'),array[pg_temp.sv('ep2'),pg_temp.sv('ep1')])->'items'->0->>'title'),'Parte 2','grava a ordem');
select throws_ok($$select pg_temp.pub('archive','serie',2)$$,'40001',null,'série com episódios publicados não é arquivada');
reset role;
set local role anon;
select is((select string_agg(e->>'title',',' order by (e->>'episode')::int) from jsonb_array_elements(public.member_series(pg_temp.sv('org'),pg_temp.sv('a'))->'items'->0->'episodes') e),'Parte 2,Parte 1','app recebe a série com episódios em ordem');
select is(public.member_series(pg_temp.sv('org'),pg_temp.sv('a'))->'items'->0->>'description','Descrição de Série Esperança','app recebe a descrição');
select is(jsonb_array_length(public.member_series(pg_temp.sv('org'),pg_temp.sv('b'))->'items'),0,'outra igreja não recebe');
select is((select x->>'series_title' from jsonb_array_elements(public.member_media(pg_temp.sv('org'),pg_temp.sv('a'),'video',0)->'items') x where x->>'title'='Parte 1'),'Série Esperança','biblioteca informa a série do vídeo');
select is((select x->>'episode' from jsonb_array_elements(public.member_media(pg_temp.sv('org'),pg_temp.sv('a'),'video',0)->'items') x where x->>'title'='Parte 1'),'2','e o número do episódio');
select is((select x->>'series_title' from jsonb_array_elements(public.member_media(pg_temp.sv('org'),pg_temp.sv('a'),'video',0)->'items') x where x->>'title'='Avulso'),'','vídeo avulso sem série');
reset role;
select pg_temp.actor('reader');set local role authenticated;
select throws_ok($$select public.publishing_series_episodes(pg_temp.sv('org'),pg_temp.sv('a'),pg_temp.sv('serie'),array[pg_temp.sv('ep1'),pg_temp.sv('ep2')])$$,'42501',null,'membro não reordena');
select throws_ok($$select pg_temp.pub('save','x',0,pg_temp.fields('series','Invasão'))$$,'42501',null,'membro não cria série');
reset role;
select ok(not has_function_privilege('anon','public.publishing_series_episodes(uuid,uuid,uuid,uuid[])','EXECUTE'),'ordem sem acesso anônimo');
select * from finish();
rollback;
